UPDATE packages SET tours_id = db.tours_id, title = db.title, description = db.description, additional_info = db.additional_info, price = db.price, status = db.status FROM( VALUES
( #{item.id}, #{toursId}, #{item.title}, #{item.description}, #{item.additionalInfo}, #{item.price}, 'PUBLISHED' )
) AS db ( id, tours_id, title, description, additional_info, price, status ) WHERE packages.id = db.id
